from datetime import datetime
from .uc_test import UcTest


class UcFtp(UcTest):
    """Implementation of UltraCaller FTP test"""

    def get_average_throughput(self):
        """
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()'
        if data transfer is already finished
        :return: value of Average throughput in unit: Kbits/sec
        """
        statistics = self._uc_connection.get_test_result(imei=self._configuration['imei'], test_id=self._test_id)
        return int(self._calculate_tp(statistics['testResult']))

    def _calculate_tp(self, statistics):
        throughput = []
        for item in statistics:
            if 'start' in list(item.keys()):
                self.start_time = datetime.fromtimestamp(item['start']).strftime('%Y/%d/%m %H:%M')
            if 'completed' in list(item.keys()):
                self.stop_time = datetime.fromtimestamp(item['completed']).strftime('%Y/%d/%m %H:%M')
            if 'result' in list(item.keys()) and 'throughput' in list(item['result'].keys()):
                throughput.append(item['result']['throughput'])
        return round(sum(throughput) / float(len(throughput)), 0)
